#include "../common.h"
int main(void){char sq[]="MFHIKUNOPQZVWXYELARGDSTBC",s[500];printf("Message: ");fgets(s,sizeof s,stdin);char p[1000];int n=0;for(int i=0;s[i];i++)if(isalpha((unsigned char)s[i]))p[n++]=toupper(s[i])=='J'?'I':toupper(s[i]);for(int i=0;i<n;i+=2){if(i+1==n||p[i]==p[i+1])p[n++]='X';}for(int i=0;i<n;i+=2){int a=0,b=0,c=0,d=0;for(int j=0;j<25;j++){if(sq[j]==p[i])a=j/5,b=j%5;if(sq[j]==p[i+1])c=j/5,d=j%5;}if(a==c)p[i]=sq[a*5+(b+1)%5],p[i+1]=sq[c*5+(d+1)%5];else if(b==d)p[i]=sq[((a+1)%5)*5+b],p[i+1]=sq[((c+1)%5)*5+d];else p[i]=sq[a*5+d],p[i+1]=sq[c*5+b];}p[n]=0;printf("Ciphertext: %s\n",p);}
